function normalizeFa(s) {
  if (s === undefined || s === null) return '';
  let t = String(s);
  t = t.replace(/\u064A/g, '\u06CC').replace(/\u0643/g, '\u06A9');
  t = t.replace(/[\u200C\u200B]/g, ' ');
  const faDigits = '۰۱۲۳۴۵۶۷۸۹';
  t = t.replace(/[۰-۹]/g, function (d) { return String(faDigits.indexOf(d)); });
  t = t.replace(/\s+/g, ' ').trim();
  return t;
}
const b = ($input.first().json.body) || $input.first().json;
const code = normalizeFa(b.uniqueCode || b.unique_code || '');
let d = (b.date || '').toString().trim();
if (!/^\d{4}-\d{2}-\d{2}$/.test(d)) { d = new Date().toISOString().slice(0, 10); }
return [{ json: { code: code, absenceDate: d, valid: !!code } }];

function toJalali(d) {
  var gy = d.getUTCFullYear(), gm = d.getUTCMonth() + 1, gd = d.getUTCDate();
  var g_d_m = [0, 31, 59, 90, 120, 151, 181, 212, 243, 273, 304, 334];
  var jy = (gy <= 1600) ? 0 : 979;
  gy -= (gy <= 1600) ? 621 : 1600;
  var gy2 = (gm > 2) ? (gy + 1) : gy;
  var days = (365 * gy) + Math.floor((gy2 + 3) / 4) - Math.floor((gy2 + 99) / 100) + Math.floor((gy2 + 399) / 400) - 80 + gd + g_d_m[gm - 1];
  jy += 33 * Math.floor(days / 12053);
  days %= 12053;
  jy += 4 * Math.floor(days / 1461);
  days %= 1461;
  if (days > 365) { jy += Math.floor((days - 1) / 365); days = (days - 1) % 365; }
  var jm, jd;
  if (days < 186) { jm = 1 + Math.floor(days / 31); jd = 1 + (days % 31); }
  else { jm = 7 + Math.floor((days - 186) / 30); jd = 1 + ((days - 186) % 30); }
  function p2(n) { return String(n).length < 2 ? '0' + n : String(n); }
  return jy + '/' + p2(jm) + '/' + p2(jd);
}
const j = $input.first().json;
const dateStr = $('نرمال‌سازی ورودی غیبت').item.json.absenceDate;
j.jalaliDate = toJalali(new Date(dateStr + 'T00:00:00Z'));
return [{ json: j }];
